import{_ as o,o as t,c as n,a3 as r}from"./chunks/framework.BwzYn71E.js";const h=JSON.parse('{"title":"Reference for Common Production-Line Concepts","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://kokobird28144.github.io/endfield-skydoc/reference-for-common-production-line-concepts"}]],"lang":"en-US","translationSource":{"title":"常见的产线概念参考","archivedAt":"2026-10-23T14:20:34.857Z","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=o9kjkkGHPc7L0TwLLeJBx2","scope":"page"}},"headers":[],"relativePath":"reference-for-common-production-line-concepts.md","filePath":"logistics/src/page-o9kjkkGHPc7L0TwLLeJBx2.md","lastUpdated":null}'),a={name:"reference-for-common-production-line-concepts.md"};function i(s,e,c,p,u,l){return t(),n("div",null,[...e[0]||(e[0]=[r('<div class="logistics-content"><span class="logistics-source-anchor" id="常见的产线概念参考" aria-hidden="true"></span><h1 id="reference-for-common-production-line-concepts" tabindex="-1">Reference for Common Production-Line Concepts <a class="header-anchor" href="#reference-for-common-production-line-concepts" aria-label="Permalink to &quot;Reference for Common Production-Line Concepts&quot;">​</a></h1><blockquote><p>Source page ID: <code>o9kjkkGHPc7L0TwLLeJBx2</code> | <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=o9kjkkGHPc7L0TwLLeJBx2" target="_blank" rel="noreferrer">Open in Tencent Docs</a></p></blockquote><p>Some simple, self-explanatory qualifiers: low-spec / visually appealing / stable / high-output / expandable with modules / easy to deploy.</p><p><strong>Gross output:</strong> Stock Bill output without considering power consumption or the exchange-rate cap on Stock Bills, measured by the Stock Bills before exchange.</p><p><strong>Net output:</strong> Stock Bill output that accounts for power consumption, based on gross output.</p><p><strong>Maximum gross output:</strong> In the narrow sense, with unlimited storage and after running for a sufficiently long time, the line&#39;s average gross output reaches the theoretical maximum gross output corresponding to the current raw-material output. In the broad sense, under specified storage conditions and after running for a sufficiently long time, the line&#39;s average gross output reaches that theoretical maximum.</p><p><strong>Maximum net output without mixed production:</strong> With unlimited storage and after running for a sufficiently long time, the line&#39;s average net output reaches the theoretical maximum net output obtained by direct quantification of the current raw-material output.</p><p><strong>Maximum net output with mixed production:</strong> Based on the maximum net output without mixed production, mixed production saves power and achieves the theoretical maximum net output that accounts for mixed production.</p><p><strong>No-goods-switching plan:</strong> For each base, sell only one type of goods while reaching the Stock Bill cap, without considering the value of output beyond the Stock Bill exchange-rate cap. The goods sold by each base then never need to be changed.</p><p><strong>Astonishing Wisdom plan group:</strong> A concept proposed by PL. Based on the no-goods-switching plan, all bases are assigned the same type of goods because Wuling has excessive surplus capacity. Only the necessary batteries and exchange goods need to be produced.</p></div>',1)])])}const m=o(a,[["render",i]]);export{h as __pageData,m as default};
